1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	const basePremiumOf = (item: Item): number =>
29	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
30	
31	const itemModifierRateOf = (item: Item): number =>
32	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
33	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
34	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
35	    : 0);
36	
37	const premiumOf = (item: Item): number =>
38	  basePremiumOf(item) * (1 + itemModifierRateOf(item));
39	
40	const sumItemPremiums = (items: Item[]): number =>
41	  items.reduce((sum, item) => sum + premiumOf(item), 0);
42	
43	const FIRST_INSURANCE_SURCHARGE_NUMERATOR = 11;
44	const FIRST_INSURANCE_SURCHARGE_DENOMINATOR = 10;
45	
46	const BLOCK_SIZE = 3;
47	const BLOCK_BASE_PREMIUM = 60;
48	
49	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
50	  sameTypeGroup.length === BLOCK_SIZE;
51	
52	const groupByType = (items: Item[]): Item[][] => {
53	  const groups = new Map<string, Item[]>();
54	  for (const item of items) {
55	    const group = groups.get(item.type) ?? [];
56	    group.push(item);
57	    groups.set(item.type, group);
58	  }
59	  return [...groups.values()];
60	};
61	
62	const premiumOfGroup = (sameTypeGroup: Item[]): number =>
63	  isComponentBlock(sameTypeGroup)
64	    ? BLOCK_BASE_PREMIUM
65	    : sumItemPremiums(sameTypeGroup);
66	
67	export const quote = (customer: Customer, items: Item[]): number => {
68	  const policyPremium = groupByType(items).reduce(
69	    (sum, group) => sum + premiumOfGroup(group),
70	    0,
71	  );
72	
73	  const withFirstInsuranceSurcharge =
74	    (policyPremium * FIRST_INSURANCE_SURCHARGE_NUMERATOR) /
75	    FIRST_INSURANCE_SURCHARGE_DENOMINATOR;
76	
77	  return withFirstInsuranceSurcharge + PROCESSING_FEE;
78	};
79	
80	export const claim = (): number => {
81	  return undefined as unknown as number;
82	};
